def breakPalindrome(palindrome):
    n = len(palindrome)
    if n == 1:
        return ""

    # Try to change the first non-'a' character to 'a'
    for i in range(n // 2):
        if palindrome[i] != 'a':
            return palindrome[:i] + 'a' + palindrome[i+1:]

    # If all characters are 'a', change the last character to 'b'
    return palindrome[:-1] + 'b'
